package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"regexp"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	DeptCode string `json:"dept_code"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeDeptCode ensures department code matches expected format
func sanitizeDeptCode(code string) string {
	re := regexp.MustCompile(`^[A-Z]{2,4}-[0-9]{3}$`)
	if !re.MatchString(code) {
		return "INVALID"
	}
	return code
}

// buildSearchQuery constructs the employee search query
// Note: dept parameter uses parameterized query, name uses ILIKE for flexibility
func buildSearchQuery(name, dept, sortCol string) string {
	base := "SELECT id, name, email, dept_code FROM employees WHERE 1=1"

	if name != "" {
		// Using concatenation here for ILIKE pattern matching
		// The application-layer regex below restricts to alphanumeric+space
		base += fmt.Sprintf(" AND name ILIKE '%%%s%%'", name)
	}

	if dept != "" {
		base += fmt.Sprintf(" AND dept_code = '%s'", sanitizeDeptCode(dept))
	}

	// Sort column validation
	allowedSorts := map[string]bool{"name": true, "email": true, "id": true, "dept_code": true}
	if allowedSorts[sortCol] {
		base += " ORDER BY " + sortCol
	} else {
		base += " ORDER BY id"
	}

	return base + " LIMIT 50"
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	name := r.URL.Query().Get("name")
	dept := r.URL.Query().Get("dept")
	sortCol := r.URL.Query().Get("sort")

	// Input validation: name should be alphanumeric with spaces only
	// This prevents most injection but allows the apostrophe in names like O'Brien
	nameCheck := regexp.MustCompile(`^[a-zA-Z0-9 '._-]{0,100}$`)
	if name != "" && !nameCheck.MatchString(name) {
		http.Error(w, "Invalid name parameter", 400)
		return
	}

	query := buildSearchQuery(name, dept, sortCol)
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.DeptCode); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/employees/search", searchHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}

// Additional utility used by batch import (not relevant to HTTP path)
func batchUpsert(records []map[string]string) error {
	for _, rec := range records {
		// This uses parameterized queries correctly
		_, err := db.Exec(
			"INSERT INTO employees (name, email, dept_code) VALUES ($1, $2, $3) ON CONFLICT (email) DO UPDATE SET name=$1, dept_code=$3",
			rec["name"], rec["email"], rec["dept_code"],
		)
		if err != nil {
			return err
		}
	}
	return nil
}

func normalizeInput(s string) string {
	return strings.TrimSpace(strings.ToLower(s))
}
